let parsed;
try {
  const raw = $input.first().json.content || $input.first().json.text || $input.first().json.output;
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  parsed = { recipient: null, amount: null };
}
return [{ json: { recipient: parsed.recipient, amount: parsed.amount } }];

// Pass the middleware's decision through UNCHANGED. The AI agent renders
// the authorization result; it does not reinterpret, override, or embellish it.
return [{ json: $input.first().json }];
